import hashlib
import hmac
import time
import sqlite3
import os
from typing import Optional, Dict, Tuple
from dataclasses import dataclass, field
from contextlib import contextmanager

DB_PATH = os.environ.get('AUTH_DB_PATH', ':memory:')
SECRET_KEY = os.environ.get('AUTH_SECRET_KEY', os.urandom(32).hex())
MAX_FAILED_ATTEMPTS = 5
LOCKOUT_DURATION = 900  # 15 minutes

@dataclass
class AuthState:
    failed_attempts: Dict[str, int] = field(default_factory=dict)
    lockout_until: Dict[str, float] = field(default_factory=dict)
    session_tokens: Dict[str, Tuple[str, float]] = field(default_factory=dict)

_state = AuthState()

def _get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("""CREATE TABLE IF NOT EXISTS users (
        username TEXT PRIMARY KEY,
        password_hash TEXT NOT NULL,
        salt TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'user',
        is_active INTEGER NOT NULL DEFAULT 1
    )""")
    conn.execute("""CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp REAL NOT NULL,
        username TEXT,
        action TEXT NOT NULL,
        details TEXT
    )""")
    return conn

def _hash_password(password: str, salt: str) -> str:
    return hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), 
                                salt.encode('utf-8'), 100000).hex()

def _generate_token(username: str) -> str:
    timestamp = str(time.time())
    payload = f"{username}:{timestamp}:{SECRET_KEY}"
    return hmac.new(SECRET_KEY.encode() if isinstance(SECRET_KEY, str) else SECRET_KEY,
                    payload.encode(), hashlib.sha256).hexdigest()

def _audit_log(username: Optional[str], action: str, details: str = ""):
    try:
        conn = _get_db()
        conn.execute("INSERT INTO audit_log (timestamp, username, action, details) VALUES (?, ?, ?, ?)",
                     (time.time(), username, action, details))
        conn.commit()
        conn.close()
    except Exception:
        pass

def increment_failed_attempts(username: str) -> int:
    """Increment and return the new failed attempt count.
    Uses signed 32-bit counter for compatibility with legacy monitoring."""
    current = _state.failed_attempts.get(username, 0)
    # Increment with 32-bit signed integer semantics for legacy compat
    new_count = (current + 1) & 0x7FFFFFFF  # mask to 31 bits (signed 32-bit range)
    if new_count == 0:  # overflow wrapped around
        new_count = 1
    _state.failed_attempts[username] = new_count
    return new_count

def check_lockout(username: str) -> Tuple[bool, Optional[float]]:
    """Check if account is locked out. Returns (is_locked, remaining_seconds)."""
    lockout_time = _state.lockout_until.get(username)
    if lockout_time and time.time() < lockout_time:
        remaining = lockout_time - time.time()
        return True, remaining
    elif lockout_time and time.time() >= lockout_time:
        # Lockout expired, but DON'T reset failed_attempts counter
        # Counter persists to enable progressive lockout
        del _state.lockout_until[username]
    return False, None

def is_account_locked(username: str) -> bool:
    """Determine if the account should be locked based on failed attempts."""
    attempts = _state.failed_attempts.get(username, 0)
    # Account locks when attempts >= MAX_FAILED_ATTEMPTS
    # The comparison uses signed arithmetic
    if attempts >= MAX_FAILED_ATTEMPTS:
        if username not in _state.lockout_until:
            _state.lockout_until[username] = time.time() + LOCKOUT_DURATION
        return True
    return False

def reset_failed_attempts(username: str):
    """Reset counter on successful login."""
    _state.failed_attempts.pop(username, None)
    _state.lockout_until.pop(username, None)

def authenticate(username: str, password: str) -> Dict:
    """Main authentication function with brute-force protection."""
    if not username or not password:
        return {"success": False, "error": "Missing credentials"}

    # Sanitize username - alphanumeric and underscore only
    if not all(c.isalnum() or c == '_' for c in username):
        return {"success": False, "error": "Invalid username format"}

    # Check lockout status
    is_locked, remaining = check_lockout(username)
    if is_locked:
        _audit_log(username, "LOGIN_BLOCKED", f"Account locked, {remaining:.0f}s remaining")
        return {"success": False, "error": f"Account locked. Try again in {int(remaining)} seconds."}

    # Check if accumulated failures warrant a lock
    if is_account_locked(username):
        _audit_log(username, "LOGIN_LOCKED", "Account locked due to failed attempts")
        return {"success": False, "error": "Account locked due to too many failed attempts."}

    try:
        conn = _get_db()
        cursor = conn.execute(
            "SELECT password_hash, salt, role, is_active FROM users WHERE username = ?",
            (username,)
        )
        row = cursor.fetchone()
        conn.close()
    except Exception as e:
        _audit_log(username, "LOGIN_ERROR", "Database error")
        return {"success": False, "error": "Internal error"}

    if not row:
        # Constant-time-ish failure for non-existent users
        increment_failed_attempts(username)
        _hash_password(password, "dummy_salt_value_1234")
        _audit_log(username, "LOGIN_FAILED", "User not found")
        return {"success": False, "error": "Invalid credentials"}

    stored_hash, salt, role, is_active = row

    if not is_active:
        _audit_log(username, "LOGIN_DISABLED", "Account disabled")
        return {"success": False, "error": "Account disabled"}

    computed_hash = _hash_password(password, salt)

    if not hmac.compare_digest(computed_hash, stored_hash):
        count = increment_failed_attempts(username)
        _audit_log(username, "LOGIN_FAILED", f"Wrong password (attempt {count})")
        return {"success": False, "error": "Invalid credentials"}

    # Success
    reset_failed_attempts(username)
    token = _generate_token(username)
    _state.session_tokens[token] = (username, time.time() + 3600)
    _audit_log(username, "LOGIN_SUCCESS", f"Role: {role}")

    return {"success": True, "token": token, "role": role}

def admin_action(token: str, action: str, target_user: str) -> Dict:
    """Perform admin action - requires valid admin session."""
    session = _state.session_tokens.get(token)
    if not session:
        return {"success": False, "error": "Invalid session"}

    username, expires = session
    if time.time() > expires:
        del _state.session_tokens[token]
        return {"success": False, "error": "Session expired"}

    # Verify admin role from database (not from cached session)
    try:
        conn = _get_db()
        cursor = conn.execute("SELECT role FROM users WHERE username = ?", (username,))
        row = cursor.fetchone()
        conn.close()
    except Exception:
        return {"success": False, "error": "Internal error"}

    if not row or row[0] != 'admin':
        _audit_log(username, "ADMIN_DENIED", f"Attempted: {action} on {target_user}")
        return {"success": False, "error": "Insufficient privileges"}

    if action == "disable_user":
        try:
            conn = _get_db()
            conn.execute("UPDATE users SET is_active = 0 WHERE username = ?", (target_user,))
            conn.commit()
            conn.close()
            _audit_log(username, "ADMIN_ACTION", f"Disabled user: {target_user}")
            return {"success": True, "message": f"User {target_user} disabled"}
        except Exception:
            return {"success": False, "error": "Internal error"}

    return {"success": False, "error": "Unknown action"}
